# ---------------------------------------------------------------- 8-сабақ
OPT = ("def fold(e):\n"
       "    \"\"\"тұрақтыларды бүктеу: екі балалары да сан болатын түйінді алдын ала есептеу\"\"\"\n"
       "    if not isinstance(e, tuple):\n"
       "        return e\n"
       "    op, a, b = e[0], fold(e[1]), fold(e[2])\n"
       "    if isinstance(a, int) and isinstance(b, int):\n"
       "        return {'+': a + b, '-': a - b, '*': a * b}[op]\n"
       "    if op == '*' and (a == 0 or b == 0):\n"
       "        return 0                    # x * 0 = 0 (x - бүтін сан, жанама әсерсіз)\n"
       "    if op == '+' and b == 0: return a\n"
       "    if op == '*' and b == 1: return a\n"
       "    return (op, a, b)\n\n"
       "def ev(e, env):\n"
       "    if isinstance(e, int): return e\n"
       "    if isinstance(e, str): return env[e]\n"
       "    a, b = ev(e[1], env), ev(e[2], env)\n"
       "    return {'+': a + b, '-': a - b, '*': a * b}[e[0]]\n\n"
       "tree = ('+', ('*', ('+', 2, 3), 'x'), ('*', ('-', 'y', 'y'), ('+', 0, 0)))\n"
       "print('бастапқы:', tree)\n"
       "print('бүктелген:', fold(tree))\n\n"
       "# Өлі кодты жою: нәтижеге әсер етпейтін меншіктеулерді кері ретпен табу\n"
       "prog = [('a', ('+', 'x', 1)), ('b', ('*', 'a', 2)), ('c', ('+', 'x', 'x')), ('a', ('-', 'b', 3)), ('out', ('+', 'a', 0))]\n"
       "def uses(e):\n"
       "    return set() if isinstance(e, int) else {e} if isinstance(e, str) else uses(e[1]) | uses(e[2])\n"
       "live, kept = {'out'}, []\n"
       "for dst, e in reversed(prog):\n"
       "    if dst in live:\n"
       "        kept.append((dst, e))\n"
       "        live = (live - {dst}) | uses(e)\n"
       "print('қалғаны:', list(reversed(kept)))")

