STACK = ("def depth(e):\n"
         "    \"\"\"стек машинасында есептеу үшін ең үлкен стек тереңдігі\"\"\"\n"
         "    if not isinstance(e, tuple):\n"
         "        return 1\n"
         "    return max(depth(e[1]), depth(e[2]) + 1)\n\n"
         "def gen(e):\n"
         "    if isinstance(e, int):\n"
         "        return [('PUSH', e)]\n"
         "    if isinstance(e, str):\n"
         "        return [('LOAD', e)]\n"
         "    return gen(e[1]) + gen(e[2]) + [({'+': 'ADD', '-': 'SUB', '*': 'MUL'}[e[0]],)]\n\n"
         "def vm(code, env):\n"
         "    st, peak = [], 0\n"
         "    for ins in code:\n"
         "        op = ins[0]\n"
         "        if op == 'PUSH':\n"
         "            st.append(ins[1])\n"
         "        elif op == 'LOAD':\n"
         "            st.append(env[ins[1]])\n"
         "        else:\n"
         "            b, a = st.pop(), st.pop()\n"
         "            st.append({'ADD': a + b, 'SUB': a - b, 'MUL': a * b}[op])\n"
         "        peak = max(peak, len(st))\n"
         "    return st.pop(), peak\n\n"
         "left = ('+', ('+', ('+', 'a', 'b'), 'c'), 'd')      # ((a+b)+c)+d\n"
         "right = ('+', 'a', ('+', 'b', ('+', 'c', 'd')))     # a+(b+(c+d))\n"
         "env = {'a': 1, 'b': 2, 'c': 3, 'd': 4}\n"
         "for name, t in [('сол жақ', left), ('оң жақ', right)]:\n"
         "    val, peak = vm(gen(t), env)\n"
         "    print(f'{name}: мәні {val}, нақты ең үлкен тереңдік {peak}, формула {depth(t)}')")

