# ---------------------------------------------------------------- 10-сабақ
COMPILER = (LEX + "\n"
            "BP = {'+': (10, 11), '-': (10, 11), '*': (20, 21)}\n\n"
            "def parse_expr(toks):\n"
            "    pos = 0\n"
            "    def expr(min_bp):\n"
            "        nonlocal pos\n"
            "        t = toks[pos]; pos += 1\n"
            "        if t == '(':\n"
            "            left = expr(0); pos += 1\n"
            "        else:\n"
            "            left = int(t) if t.isdigit() else t\n"
            "        while pos < len(toks) and toks[pos] in BP and BP[toks[pos]][0] >= min_bp:\n"
            "            op = toks[pos]; pos += 1\n"
            "            left = (op, left, expr(BP[op][1]))\n"
            "        return left\n"
            "    return expr(0)\n\n"
            "def parse_program(src):\n"
            "    stmts = []\n"
            "    for n, line in enumerate(src.strip().split('\\n'), 1):\n"
            "        toks = [t for _, t in lex(line)]\n"
            "        if toks[0] == 'let':\n"
            "            stmts.append(('let', toks[1], parse_expr(toks[3:]), n))\n"
            "        else:\n"
            "            stmts.append(('print', parse_expr(toks[1:]), n))\n"
            "    return stmts\n\n"
            "def check(stmts):\n"
            "    defined, errors = set(), []\n"
            "    def names(e):\n"
            "        return set() if isinstance(e, int) else {e} if isinstance(e, str) else names(e[1]) | names(e[2])\n"
            "    for s in stmts:\n"
            "        e = s[2] if s[0] == 'let' else s[1]\n"
            "        for x in sorted(names(e) - defined):\n"
            "            errors.append(f'{s[-1]}-жол: «{x}» анықталмаған')\n"
            "        if s[0] == 'let':\n"
            "            defined.add(s[1])\n"
            "    return errors\n\n"
            "def fold(e):\n"
            "    if not isinstance(e, tuple):\n"
            "        return e\n"
            "    op, a, b = e[0], fold(e[1]), fold(e[2])\n"
            "    if isinstance(a, int) and isinstance(b, int):\n"
            "        return {'+': a + b, '-': a - b, '*': a * b}[op]\n"
            "    return (op, a, b)\n\n"
            "def gen(e):\n"
            "    if isinstance(e, int): return [('PUSH', e)]\n"
            "    if isinstance(e, str): return [('LOAD', e)]\n"
            "    return gen(e[1]) + gen(e[2]) + [({'+': 'ADD', '-': 'SUB', '*': 'MUL'}[e[0]],)]\n\n"
            "def compile_program(src):\n"
            "    stmts = parse_program(src)\n"
            "    errors = check(stmts)\n"
            "    if errors:\n"
            "        raise NameError('; '.join(errors))\n"
            "    code = []\n"
            "    for s in stmts:\n"
            "        if s[0] == 'let':\n"
            "            code += gen(fold(s[2])) + [('STORE', s[1])]\n"
            "        else:\n"
            "            code += gen(fold(s[1])) + [('PRINT',)]\n"
            "    return code\n\n"
            "def vm(code):\n"
            "    st, mem, out = [], {}, []\n"
            "    for ins in code:\n"
            "        op = ins[0]\n"
            "        if op == 'PUSH': st.append(ins[1])\n"
            "        elif op == 'LOAD': st.append(mem[ins[1]])\n"
            "        elif op == 'STORE': mem[ins[1]] = st.pop()\n"
            "        elif op == 'PRINT': out.append(st.pop())\n"
            "        else:\n"
            "            b, a = st.pop(), st.pop()\n"
            "            st.append({'ADD': a + b, 'SUB': a - b, 'MUL': a * b}[op])\n"
            "    return out\n")

COMPILER_DEMO = (COMPILER + "\n"
                 "src = '''\n"
                 "let seconds = 2 * 60 * 60\n"
                 "let price = 450\n"
                 "let total = price * 3 - 100\n"
                 "print total\n"
                 "print seconds + total * 0\n"
                 "'''\n"
                 "code = compile_program(src)\n"
                 "print(len(code), 'команда:', code[:4], '...')\n"
                 "print('шығыс:', vm(code))\n"
                 "try:\n"
                 "    compile_program('let a = 1\\nprint a + b')\n"
                 "except NameError as e:\n"
                 "    print('компиляция қатесі:', e)")

